\begin{rem}
Let us mention that the mapping $T$ is an isomorphism
$\Qsym[t_1,t_2,\dots][\alpha]\to\Qsym[t,t_1,t_2,\dots][\alpha]$, while
$\Phi$ is an injection and its image is described by the condition:
$p(t)\in\Phi(\mathcal{P})$ is and only if $\Phi(-t)p(t)\in\mathcal{P}$.
\end{rem}
On the ring of simple polytopes we have
$f(\alpha,t_1,t_2,\dots)(p)=f_1(\alpha,t_1+t_2+\dots)(p)=f_1(\alpha,\sigma_1)(p)$,
so the image of $\mathcal P_s$ belongs to $\mathbb Z[\alpha,\sigma_1]$. On
the other hand, $\Phi(t)=e^{td}$, so we have the condition
$f_1(\alpha,t_1)(e^{td}p)=f_1(\alpha,t+t_1)(p)$.
\begin{prop}\label{Simple}
Let $\psi:\mathcal{P}_s\to\mathbb Z[\alpha,t]$ be a linear mapping such that
\begin{enumerate}
\item $\psi(\alpha,0)(P^n)=\alpha^n$;
\item One of the following equivalent conditions holds:
   \begin{enumerate}
     \item $\psi(\alpha,t_1)(e^{td}p)=\psi(\alpha,t+t_1)(p)$;
     \item $\psi(\alpha,t)(dp)=\frac{\partial}{\partial
         t}\psi(\alpha,t)(p)$.
    \end{enumerate}
\end{enumerate}
Then $\psi=f_1$.
\end{prop}
\begin{proof}
Let conditions $1$ and $2a$ hold. Then
$$
\psi(\alpha,t+t_1)(p)=\psi(\alpha,t_1)(e^{td}p)=\psi(\alpha,0)(e^{(t+t_1)d}p)=\xi_{\alpha}\Phi(t+t_1)p=f_1(\alpha,t_1+t)(p).
$$

Natural Hopf comodule structure
$\mathcal{P}$ is not a Hopf algebra, but it turns out that there is a natural
Hopf comodule structure on the ring $\mathcal{P}$ over the Hopf algebra
$\mathcal{RP}$.

\begin{prop}
Formula
$$
\Delta_{\mathcal{RP}} P=\sum\limits_{F\subseteq P}F\otimes(P/F)
$$
defines a natural graded right Hopf comodule structure
$\Delta_{\mathcal{RP}}\colon\mathcal{P}\to\mathcal{P}\otimes\mathcal{RP}$ on
the ring $\mathcal{P}$ over the Hopf algebra $\mathcal{RP}$.
\end{prop}
\begin{proof}
We should proof that the following two diagrams commute
$$
\xymatrix{
\mathcal{P}\ar[d]^{\Delta_{\mathcal{RP}}}\ar[rr]^{\Delta_{\mathcal{RP}}}&&\mathcal{P}\otimes\mathcal{RP}\ar[d]^{\id\otimes\Delta}\\
\mathcal{P}\otimes\mathcal{RP}\ar[rr]^{\Delta_{\mathcal{RP}}\otimes\id}&&\mathcal{P}\otimes\mathcal{RP}\otimes\mathcal{RP}\\
}
\hspace{2cm}
\xymatrix{
\mathcal{P}\ar[d]_{\Delta_{\mathcal{RP}}}\ar[dr]^{\id\otimes 1}&\\
\mathcal{P}\otimes \mathcal{RP}\ar[r]^{\id\otimes \varepsilon}&\mathcal{P}\otimes\mathbb Z\\
}
$$
and that $\Delta_{\mathcal{RP}}$ is a ring homomorphism. Indeed, we have
\begin{multline*}
(\Delta_{\mathcal{RP}}\otimes\id)\circ\Delta_{\mathcal{RP}} P=(\Delta_{\mathcal{RP}}\otimes\id)\left(\sum\limits_{F\subseteq P}F\otimes P/F\right)=\sum\limits_{F\subseteq P}\left(\sum\limits_{G\subseteq F}G\otimes F/G\right)\otimes P/F=\\
=\sum\limits_{G\subseteq P}G\otimes\left(\sum\limits_{G\subseteq F\subseteq
P}F/G\otimes P/F\right)=\sum\limits_{G\subseteq P}G\otimes\Delta (P/G)
=(\id\otimes\Delta)\circ\Delta_{\mathcal{RP}} P,
\end{multline*}
and
$$ (\id\otimes\varepsilon)\circ\Delta_{\mathcal{RP}}(P)=\sum\limits_{F\subseteq
P}F\otimes\varepsilon(P/F)=P\otimes 1,
$$

Let us check that $\Delta_{\mathcal{RP}}$ is a homomorphism of rings
$\mathcal{P}\to\mathcal{P}\otimes\mathcal{RP}$:
\begin{multline*}
\Delta_{\mathcal{RP}}(P\times Q)=\sum\limits_{F\times G\subseteq P\times
Q}(F\times G)\otimes \left(P\times Q/ F\times G\right)=
\sum\limits_{F\subseteq P,\,G\subseteq Q}(F\times G)\otimes \left(P/F\divideontimes Q/G\right)=\\
=\left(\sum\limits_{F\subseteq P}F\otimes
P/F\right)\cdot\left(\sum\limits_{G\subseteq Q}G\otimes
Q/G\right)=\Delta_{\mathcal{RP}}(P)\cdot\Delta_{\mathcal{RP}}(Q)
\end{multline*}
$$
\Delta_{\mathcal{RP}}(\pt)=\pt\otimes (\pt/\pt)=\pt\otimes \varnothing=1\otimes 1.
$$
\end{proof}

\begin{cor}
\begin{itemize}
\item Any ring homomorphism $\mathcal{P}\to\mathcal{A}$, where
    $\mathcal{A}$ is a ring, induces the ring homomorphism
    $\mathcal{P}\to\mathcal{A}\otimes\mathcal{RP}$
\item Any linear homomorphism $\psi\colon\mathcal{RP}\to\mathbb Z$
    induces the linear operator $\mathcal{P}\to\mathcal{P}$, which is a
    ring homomorphism, if $\psi$ is a ring homomorphism.
\end{itemize}
\end{cor}

\begin{exam}
The homomorphism $\xi_{\alpha}\colon\mathcal{P}\to\mathbb Z[\alpha]$ defines
the ring homomorphism $l_{\alpha}\colon\mathcal{P}\to\mathcal{RP}[\alpha]$:
$$
l_{\alpha}(P^n)=\sum\limits_{F\subseteq P}\alpha^{\dim F}P/F.
$$
Let us recall that in the case of a simple $n$-polytope a face polytope of an
$i$-dimensional face is a simplex $\Delta^{n-i-1}=x^{n-i}$. Therefore,
$$
l_{\alpha}(P^n)=\sum\limits_{i=0}^nf_i\alpha^ix^{n-i}=f_1(\alpha,x).
$$
This is a homogeneous $f$-polynomial in two variables defined in \cite{Buch}.
\end{exam}

\begin{prop}\label{DPQ}
\begin{equation}
\Delta_{\mathcal{RP}}(P\divideontimes Q)=(1\otimes P)\cdot\Delta_{\mathcal{RP}}(Q)+\Delta_{\mathcal{RP}}(P)\cdot (1\otimes Q)+\Delta_{\mathcal{RP}}(P)(\divideontimes\otimes\divideontimes) \Delta_{\mathcal{RP}}(Q)\label{FDPQ}
\end{equation}
\end{prop}
\begin{proof}
\begin{multline*}
\Delta_{\mathcal{RP}}(P\divideontimes Q)=\sum\limits_{G\subseteq Q}
\left(\varnothing\divideontimes G\right)\otimes \left(P\divideontimes
Q/\varnothing \divideontimes G\right)+\sum\limits_{F\subseteq P}
\left(F\divideontimes\varnothing\right)\otimes \left(P\divideontimes
Q/F \divideontimes \varnothing\right)+\\
+\sum\limits_{F\subseteq P,\,G\subseteq Q}(F\divideontimes  G)\otimes
\left(P\divideontimes Q/F\divideontimes G\right)=\sum\limits_{G\subseteq Q}
G\otimes \left(P\divideontimes (Q/G)\right)+
\sum\limits_{F\subseteq P} F\otimes \left((P/F)\divideontimes Q\right)+\\
+\sum\limits_{F\subseteq P,\,G\subseteq Q}\left(F\divideontimes
G\right)\otimes\left(P/F\divideontimes Q/G\right)=(1\otimes
P)\Delta_{\mathcal{RP}}(Q)+\Delta_{\mathcal{RP}}(P)(1\otimes
Q)+\Delta_{\mathcal{RP}}(P)(\divideontimes\otimes\divideontimes)
\Delta_{\mathcal{RP}}(Q)
\end{multline*}
\end{proof}

Now if we apply $\xi_{\alpha}\otimes 1$ to the formula (\ref{FDPQ}), then we
obtain the corollary:
\begin{cor}\label{lPQ}
$$
l_{\alpha}(P\divideontimes Q)=P\divideontimes l_{\alpha}(Q)+l_{\alpha}(P)\divideontimes Q+\alpha\; l_{\alpha}(P)\cdot l_{\alpha}(Q)
$$
\end{cor}

