Preliminaries
All norms unless otherwise noted are the Euclidean--norm and the induced Euclidean--norm. The variable $t\in \Re_+$ denotes time throughout and for a differentiable function $x(t)$, $\frac{d}{dt} x(t)$ is equivalent to $\dot x(t)$. Parameters explicit time dependence $(t)$ is used upon introduction and then omitted thereafter except for emphasis. The other norms used in this work are the $\mathcal L_2$ and truncated $\mathcal L_2$ norm defined below. Given a vector $\nu \in \Re^n$ and finite $p \in\mathbb N_{>0}$, $
\norm {\nu(t)}_{L_p}    \triangleq  \left(  \int_0^\infty \norm {\nu(s)} ^p ds\right)^{1/p}$, $\norm {\nu(t)}_{L_p,\tau}  \triangleq   \left( \int_0^\tau \norm {\nu(s)} ^p ds\right)^{1/p}$ and the infinity norm is then defined as $\norml{\nu(t)}{\infty} \triangleq \sup \norm{\nu(t)}$.

\begin{defn} Given a Hurwtiz matrix $A_m\in \Re^{n\times n}$
\be
\begin{split}
\label{s1:ambound}
 \sigma& \triangleq - \max_i  \left( \text{real} (\lambda_i(A_m))  \right) \\
  s& \triangleq - \min_i  \left( \lambda_i\left(A_m+A_m^T\right)/2  \right) \\
 	  a& \triangleq \norm{A_m}. 
\end{split}
\ee 
 For ease of exposition, throughout the paper, we choose $L$ in  \eqref{s1:ref} and $\Gamma$ in \eqref{s2:adaplaw} as follows:
\begin{align}\label{s1:L} L &\triangleq  -\ell I_{n \times n} \\
\label{s1:G}\Gamma & \triangleq \gamma I_{n\times n}.
\end{align}
\end{defn}

\begin{lem}\label{sgs}
The constants $\sigma$ and $s$ are strictly positive and satisfy
\ben
s\geq\sigma>0.
\een
\end{lem}
\begin{proof}
 $A_m$ is Hurwitz and therefore $\sigma>0$. It is not necessary however that the sum $A_m+A_m^T$ is Hurwitz. The trace operator is denoted as $\text{Tr} (\cdot)$ and is a linear operator. Recalling that a matrix and its transpose have the same trace we can conclude that $\Sigma _i \lambda_i(A_m) =\Sigma _i \lambda_i(A_m+A_m^T)/2$. Finally we have that
 \ben
 s \geq -\frac 1 {2n} \sum_{i=1}^n \lambda_i\left(A_m+A_m^T\right) = -\frac 1 n \sum_{i=1}^n \lambda_i(A_m) \geq \sigma>0.  \ \IEEEQEDopen
 \een
 \let\IEEEQEDopen\relax 
\end{proof}


\begin{lem} \label{ambarbound}
With $L$  chosen as in \eqref{s1:L}, $A_m$ Hurwitz with constants $\sigma$ and $a$ as defined in \eqref{s1:ambound}, $P$ in \eqref{s1:lyap} satisfies
\begin{align}\label{s1:pbound}
 \text{(i)} & &\norm P \leq& \frac{m^2}{\sigma + 2\ell}  & &\\ 
 \text{(ii)} & &\min_i \lambda_i{(P)} \geq &\frac{1}{2(s+\ell)}& & \label{minP}
\end{align}
where $m=(1+4\varkappa)^{n-1} \text{ and } \varkappa \triangleq \frac a \sigma$.\end{lem}
\begin{proof} See Appendix \ref{pf:ambound}.\let\IEEEQEDopen\relax\end{proof}

