\begin{equation}
\!\Delta u(k|t)\!=\!\begin{cases} u(t|t)\!-\!u(t-1)\!\! & \text{if}\, k=t\\
u(k|t)\!-\!u(k\!-\!1|t)\!\! & \text{if}\, t\!+\!1\leq k\leq t\!+\!N\!-\!1 \end{cases}
\end{equation}
Moreover, we define the future regressor vectors $\varphi(k|t)\in{\mathbb R}^{n_um},\,k\in[t+1,t+N]$ as:
\begin{equation}\label{Eq:predicted_regressors}
\varphi(k|t)\!=\!\!\begin{cases} W\varphi(t)\!\!+\!\!Zu(t|t)\!\!\! & \text{if} \,\, k=t+1\\
                                                 W \varphi(k\!-\!1|t)\!\!+\!\!Zu(k\!-\!1|t) \!\!\!& \text{if} \,\, t\!+\!2\!\leq\! k\!\leq\! t\!+\!N.

In addition to the model set, the proposed SM identification algorithm also provides a nominal model of the plant (step 2) of Algorithm \ref{Alg:RHCOP2}). The latter is given by a matrix $H_{c}(t)\in {\mathbb R}^{n_y\times n_um}$, $H_c=[H_{c,1},\hdots H_{c,n_y}]^T$, where $H_{c,j}(t)\in {\mathbb R}^{n_um},\, j=1,\hdots, n_y$ are computed as the centers of the maximum volume $l_2$-norm balls inscribed in the polytopes $\mathcal{F}_{j}(t)$. This can be done by solving an LP, however the solution is not unique in general. Therefore, we introduce a regularization term, that penalizes the deviation of the new nominal model from the previous one, giving rise to the following LP:
\begin{equation}\label{Eq:central_estimate}
\begin{array}{c}
\max \limits_{\xi_j(t),H_{c,j}(t)} \sum \limits_{j=1}^{n_y}\xi_j(t)-\alpha\|H_{c,j}(t-1)-H_{c,j}(t)\|_1\\
\text{subject to}\\
a_{ji}(t)H_{c,j}(t)\!+\!\xi_j(t)\|a_{ji}(t)\|_2\!\leq\! b_{ji}(t), \, j=1,\hdots, n_y,\, i=1,\hdots, n_u,
\end{array}
\end{equation}
 where $\xi_j(t) \in {\mathbb R}$ is the radius of the maximum volume ball inscribed in $\mathcal{F}_{j}(t)$, $\alpha>0$ is a design variable, and $a_{ji}(t)$ and $b_{ji}(t)$ stand for the $i^{\text{th}}$ row of the matrix $A_j(t)$ and the vector $b_j(t)$.\\
Initially, at time step $t=0$, the matrix $H_{c}(0)$ can be taken as an arbitrary nonzero point inside the set $\mathcal{F}(0)$.
\subsection{Constrained predictive controller}\label{S:Control}
Let $u(k|t),\, k\in[t,t+N-1]$, $N\geq m$,  be the possible future control moves, where the notation $k|t$ indicates the prediction at step $k\geq t$ given the information at the current step $t$. Similarly, we define the vectors of future input increments $\Delta u(k|t), \, k\in [t,t+N-1]$ as:
\begin{equation}
\!\Delta u(k|t)\!=\!\begin{cases} u(t|t)\!-\!u(t-1)\!\! & \text{if}\, k=t\\
u(k|t)\!-\!u(k\!-\!1|t)\!\! & \text{if}\, t\!+\!1\leq k\leq t\!+\!N\!-\!1 \end{cases}
\end{equation}
Moreover, we define the future regressor vectors $\varphi(k|t)\in{\mathbb R}^{n_um},\,k\in[t+1,t+N]$ as:
\begin{equation}\label{Eq:predicted_regressors}
\varphi(k|t)\!=\!\!\begin{cases} W\varphi(t)\!\!+\!\!Zu(t|t)\!\!\! & \text{if} \,\, k=t+1\\
                                                 W \varphi(k\!-\!1|t)\!\!+\!\!Zu(k\!-\!1|t) \!\!\!& \text{if} \,\, t\!+\!2\!\leq\! k\!\leq\! t\!+\!N.
\end{cases}
\end{equation}
In addition, we define the current prediction error $\hat{d}(t)\in {\mathbb R}^{n_y}$ as the difference between the measured plant output and the one predicted by the nominal model at the time step $t$:
\begin{equation}\label{Eq:predicion_error}
\hat{d}(t)\doteq \tilde{y}(t)-H_c(t)\varphi(t).
\end{equation}
Then, we consider the following cost function:
\begin{equation} \label{Eq:cost_function}
\begin{aligned}
J(U,\tilde{y}(t),\varphi(t))\doteq \sum\limits_{k=t}^{t\!+\!N\!-\!1}\!&\!\left(\hat{y}(k\!+\!1|t)\!-\!y_{\text{des}}(k\!+\!1|t)\right)^TQ(\hat{y}(k\!+\!1|t)-\!y_{\text{des}}(k\!+\!1|t))\!+\! u(k|t)^TSu(k|t)\\&+\Delta u(k|t)^TR\Delta u(k|t),
\end{aligned}\!\!
\end{equation}
where:
\begin{equation}\label{Eq:predicted_output}
\hat{y}(k+1|t)=H_c(t)\varphi(k+1|t)+\hat{d}(t).
\end{equation}
In \eqref{Eq:cost_function}, $U=[u(t|t) \ldots u(t+N-1|t)]$ are the decision variables, while $\tilde{y}(t)$ and $\varphi(t)$ are  known parameters. $y_\text{des}(k|t),\,k\in[t+1,t+N]$, are the predicted values of the desired output. The introduction of the disturbance estimate $\hat{d}(t)$ in the cost function enables offset free tracking. Moreover, if the nominal model of the plant $H_c(t)$ were equal to the real plant, the measurement noise $v(t)$ were zero, and the output disturbance $d(t)$ were constant, for $N=T$, minimizing the cost function \eqref{Eq:cost_function} would be equivalent to minimizing the cost function of the control objective \eqref{Eq:problem_cost}.\\
Satisfaction of input constraints can be enforced by the following set of inequalities:
\begin{equation}\label{Eq:input_rate}
\begin{array}{ll}
\begin{aligned}
C u(k|t) & \leq & d\\
L \Delta u(k|t) & \leq & f
\end{aligned} & \forall k\in[t,t+N-1].
\end{array}
\end{equation}
And the robust satisfaction of the output constraints can be achieved by enforcing the latter for all the plants inside the model set $\mathcal{F}(t)$ and all disturbance realizations:
\begin{equation}\label{Eq:output1}
E(H\varphi(k|t)\!+\!d)\leq p, \, \begin{array}{l}\forall H\! \in\! \mathcal{F}(t),\, \forall d: -\epsilon_d\leq d\leq \epsilon_d,\\ \forall k\in[t\!+\!1,t\!+\!N] \end{array}
\end{equation}
The constraints \eqref{Eq:output1} are satisfied for anny disturbance realization if the following set of inequalities is satisfied: 
\begin{equation}\label{Eq:output}
EH\varphi(k|t)\!+\!\overline{d}\leq p, \, \forall H\! \in\! \mathcal{F}(t),\, \forall k\in[t\!+\!1,t\!+\!N],
\end{equation}
where $\overline{d}=[\overline{d}_1,\hdots, \overline{d}_{n_o}]^T$, and $d_l \in {\mathbb R},\, l=1,\hdots, n_o$ are given as:
\begin{equation}\label{Eq:iter_LP}
\overline{d}_l=\sum\limits_{j=1}^{n_y}|e_{lj}|\epsilon_{d_j},
\end{equation}
where $e_{lj}$ stand for the element of the $l^\text{th}$ row and $j^\text{th}$ column of the matrix $E$. However, using the constraints \eqref{Eq:output} would result in an infinite dimensional optimization problem, that is in general very hard to solve. The following result shows how \eqref{Eq:output} can be equivalently written in the form of linear constraints.
\begin{lemma}\label{L:constraint_equivalence_1}
The constraints (\ref{Eq:output}) are satisfied if and only if the following set of inequalities is feasible:
\small
\begin{equation}\label{Eq:relaxed_constraints1}
\left.\begin{array}{l}\!\!
A(t)^T\lambda_l(k|t)=\left[\begin{array}{c}
e_{l1}\varphi(k|t)\\
\vdots\\
e_{ln_y}\varphi(k|t)
\end{array}\right]\\
b(t)^T\lambda_l(k|t)\leq p_l\!-\!\overline{d}_l\\
\lambda_l(k|t)\geq \bold 0
\end{array} \right\}\begin{array}{cc}\forall l=1,\hdots,n_o\\
\forall k\!\in\![t\!+\!1,t\!+\!N]\end{array}
\end{equation}
\normalsize
with
\small
\begin{equation}\label{Eq:explanation}
\begin{aligned}
A(t)&=\left[\begin{array}{cccc} A_1(t)& \bold 0& \ldots&\bold 0\\
\bold 0& A_2(t)& \ldots& \bold 0\\
\vdots& \vdots & \ddots & \vdots \\
\bold 0&\bold 0& \ldots&A_{n_y}(t)\end{array} \right]\\
b(t)&=\left[\begin{array}{c}
b_1(t)\\
\vdots\\
b_{n_y}(t)
\end{array} \right],
\end{aligned}
\end{equation}
\normalsize
where $\bold 0$ represents zero matrices of appropriate dimensions and $j^\text{th}$ column of the matrix $E$ and $p_l$ is the $l^\text{th}$ element of the vector $p$. In \eqref{Eq:relaxed_constraints1}, $\lambda_l(k|t) \in {\mathbb R}^{r(t)}$ are additional decision variables, where $r(t)=\sum_{j=1}^{n_y} r_j(t)$.
\end{lemma}
