 	\\
&=\sum_{k = (t-s)_+}^{t-1} \sum_{k' = (t-s)_+}^{t-1} \sum_{j=1}^p \|x_j(k+1) -  x_j(k) \|\|x_j(k'+1) -  x_j(k') \| 	
 	\\
&{\leq}\sum_{k = (t-s)_+}^{t-1} \sum_{k' = (t-s)_+}^{t-1} \|\mathbf{x}(k+1) -  \mathbf{x}(k) \|\|\mathbf{x}(k'+1) -  \mathbf{x}(k') \|

