Using the same argument as in the proof of Theorem \ref{theo:telecov-weakconv-GE} in Section \ref{sec:tele-cov}, we can also get the following asymptotic bound, which generalizes Theorem 9 in \cite{HHHO09}:
\begin{proposition}\label{bisep:theorem9}
For an $m$-partite state $\rho_{\vv{A}}$ it holds that
\begin{equation}
K_D(\rho_{\vv{A}})\leq E^\infty_{GE}(\rho_{\vv{A}}).

\label{lem:fid-hyp}
The following relation holds between the hypothesis testing relative entropy and fidelity between two states $\rho,\sigma$:
\begin{align}
   &D^\varepsilon_h(\rho,\sigma) \nonumber \\
&\leq -2 \log_2 \left(\sqrt{F}(\rho,\sigma) - \sqrt{\varepsilon}\sqrt{1-\left(\sqrt{F}(\rho,\sigma)- \sqrt{\varepsilon}\right)^2}\right) \\ 
&\leq -2 \log_2 \left(\sqrt{F}(\rho,\sigma) - \sqrt{\varepsilon} \right),
\end{align}
for a fixed $\varepsilon\in[0,\sqrt{F}(\rho,\sigma))$.

\label{lem:TD-hyp}The following relation holds between the hypothesis testing relative entropy and the trace distance between any two states $\rho,\sigma$:
\begin{equation}\label{eqn:TD-hyp0}
	D^{\varepsilon}_h(\rho\Vert\sigma)\leq -\log_2 \left(1 - \frac 12 \norm{\rho - \sigma}_1 - \varepsilon \right).
\end{equation}
for a fixed $\varepsilon\in[0,1-\frac 12 \norm{\rho - \sigma}_1)$,

Let $\rho_{\vv{LA'}\vv{RB}\vv{P}}$ be a state and let $\sigma'\in\FS(:\vv{LA'}:\vv{RB}:\vv{P}:)$ and $\sigma\in\FS(:\vv{LA}:\vv{R}:\vv{PC}:)$. Then the following inequality holds
\begin{multline}
 E_{\max,E}(:\vv{LA}:\vv{R}:\vv{PC}:)_{\mc{N}(\rho)}\\ 
 \leq D_{\max}\(\mc{N}_{\vv{A'}\vv{B}\to\vv{A}\vv{C}}(\rho_{\vv{LA'}\vv{RB}\vv{P}})\Vert \sigma_{\vv{LA}\vv{R}\vv{PC}}\).
 \end{multline}
Applying the data-processed triangle inequality \cite[Theorem III.1]{CM17}, we find that
\begin{multline}
D_{\max}\(\mc{N}_{\vv{A'}\vv{B}\to\vv{A}\vv{C}}(\rho_{\vv{LA'}\vv{RB}\vv{P}})\Vert \sigma_{\vv{LA}\vv{R}\vv{PC}}\)\\
 \leq D_{\max}(\rho_{\vv{LA'}\vv{RB}\vv{P}}\Vert\sigma'_{\vv{LA'}\vv{RB}\vv{P}}) \\ 
 +D_{\max}(\mc{N}_{\vv{A'}\vv{B}\to\vv{A}\vv{C}}(\sigma'_{\vv{LA'}\vv{RB}\vv{P}})\Vert \sigma_{\vv{LA}\vv{R}\vv{PC}}).
\end{multline}
Since $\sigma'_{\vv{LA'}\vv{RB}\vv{P}}$ and $\sigma_{\vv{LA}\vv{R}\vv{PC}}$ are arbitrary fully separable states, we arrive at
\begin{multline}
E_{\max,E}(:\vv{LA}:\vv{R}:\vv{PC}:)_{\mc{N}(\rho)}
 \leq  E_{\max,E}(:\vv{LA'}:\vv{RB}:\vv{P}:)_{\rho}\\
 + E_{\max,E}(L:\vv{LA}:\vv{R}:\vv{PC}:)_{\mc{N}(\sigma')}.
\end{multline}
This implies that $E_{\max,E}^{p}(\mc{N})\leq E_{\max,E}(\mc{N})$ given that $\sigma'\in\FS(:\vv{LA'}:\vv{RB}:\vv{P}:)$. Notice that $E_{\max,E}^{p}(\mc{N})\geq E_{\max,E}(\mc{N})$ always holds. Hence, Eq.~\eqref{eq:max-amor} holds.

A quantity is called a generalized divergence \cite{PV10,SW12} if it satisfies the following monotonicity (data-processing) inequality for all density operators $\rho$ and $\sigma$ and quantum channels $\mc{N}$:
\begin{equation}\label{eq:gen-div-mono}
\mathbf{D}(\rho\Vert \sigma)\geq \mathbf{D}(\mathcal{N}(\rho)\Vert \mc{N}(\sigma)).
\end{equation}
Examples include the quantum relative entropy~\cite{Ume62} 
\begin{equation}
D(\rho\Vert\sigma)\coloneqq \Tr[\rho\log_2(\rho-\sigma)],
\end{equation}
for $\supp(\rho)\subseteq \supp(\sigma)$, otherwise it is $\infty$, as well as the sandwiched R\'enyi relative entropy  \cite{MDSFT13,WWY14} which is denoted as $\wt{D}_\alpha(\rho\Vert\sigma)$  and defined for states
$\rho,\sigma$, and  $\forall \alpha\in (0,1)\cup(1,\infty)$ as
\begin{equation}\label{eq:def_sre}
\wt{D}_\alpha(\rho\Vert \sigma):= \frac{1}{\alpha-1}\log_2 \Tr\left[\left(\sigma^{ (1-\alpha) / 2\alpha }\rho\sigma^{ (1-\alpha) / 2\alpha }\right)^\alpha \right] ,
\end{equation}
but it is set to $+\infty$ for $\alpha\in(1,\infty)$ if $\supp(\rho)\nsubseteq \supp(\sigma)$. In the limit $\alpha\to 1$ the sandwiched R\'enyi relative entropy converges to the quantum relative entropy, in the limit  $\alpha\to \infty$, it converges to the max-relative entropy \cite{MDSFT13}, which is defined as \cite{D09,Dat09}
\begin{equation}\label{eq:max-rel}
D_{\max}(\rho\Vert\sigma)\coloneqq \inf\{\lambda\in\mathbb{R}:\ \rho \leq 2^\lambda\sigma\},
\end{equation}
and if $\supp(\rho)\nsubseteq\supp(\sigma)$ then $D_{\max}(\rho\Vert\sigma)=\infty$. Another generalized divergence  is the $\varepsilon$-hypothesis-testing divergence \cite{BD10,WR12},  defined as
\begin{equation}
D^\varepsilon_h\!\(\rho\Vert\sigma\):=-\log_2\inf_{\Lambda: 0\leq\Lambda\leq \bbm{1}}\{\Tr[\Lambda\sigma]:\  \Tr[\Lambda\rho]\geq 1-\varepsilon\},
\end{equation}
for $\varepsilon\in[0,1]$ and density operators $\rho,\sigma$. For a more detailed description and other examples of the generalized divergences like the trace distance $\norm{\rho-\sigma}_{1}$ and negative of fidelity $-F(\rho,\sigma)$ and their properties, see Appendix \ref{App:Div}.

A quantity is called a generalized divergence \cite{PV10,SW12} if it satisfies the following monotonicity (data-processing) inequality for all density operators $\rho$ and $\sigma$ and quantum channels $\mc{N}$:
\begin{equation}\label{eq:gen-div-mono}
\mathbf{D}(\rho\Vert \sigma)\geq \mathbf{D}(\mathcal{N}(\rho)\Vert \mc{N}(\sigma)).
\end{equation}
As a direct consequence of the above inequality, any generalized divergence satisfies the following two properties for an isometry $U$ and a state~$\tau$ \cite{WWY14}:
\begin{align}
\mathbf{D}(\rho\Vert \sigma) & = \mathbf{D}(U\rho U^\dag\Vert U \sigma U^\dag),\label{eq:gen-div-unitary}\\
\mathbf{D}(\rho\Vert \sigma) & = \mathbf{D}(\rho \otimes \tau \Vert \sigma \otimes \tau).\label{eq:gen-div-prod}
\end{align}
